// Upstream CSS, line for line, with component-prefixed parts (data-slot),
// keyframes (rattle-bounce-*), colors and delays (--rattle-bounce-*). The
// pile is drawn left to right and mirrored as a whole in a right-to-left
// context. React 19 hoists this <style> into <head> once, however many
// instances render.
const css = `
[data-slot="rattle-bounce-pile"] {
  position: absolute;
  /* Upstream: inset: 0. A fixed 280px column (three bricks and two gaps),
     centered, keeps the 3 + 2 pile when the stage is narrower than 320px. */
  top: 0;
  bottom: 0;
  left: 50%;
  width: 280px;
  margin-left: -140px;
  display: flex;
  gap: 5px;
  flex-direction: row;
  flex-wrap: wrap;
  justify-content: center;
  align-content: center;
  flex-flow: wrap-reverse;
  direction: ltr;
}
[data-slot="rattle-bounce-pile"]:dir(rtl) {
  scale: -1 1;
}

[data-slot="rattle-bounce-brick"] {
  position: relative;
  width: 90px;
  aspect-ratio: 1 / 0.5;
  background-color: var(--rattle-bounce-1, #888);
  border-radius: 6px;
  transform-origin: bottom center;
  animation:
    rattle-bounce-bounce 0.8s ease-in-out var(--rattle-bounce-delay, 0s) both,
    rattle-bounce-fall 0.5s cubic-bezier(0.74, 0.03, 1, 1) calc(var(--rattle-bounce-delay, 0s) + 1.4s)
      forwards;
}
[data-slot="rattle-bounce-brick"]:nth-child(1) {
  --rattle-bounce-delay: 0.1s;
}
[data-slot="rattle-bounce-brick"]:nth-child(2) {
  --rattle-bounce-delay: 0.3s;
}
[data-slot="rattle-bounce-brick"]:nth-child(3) {
  --rattle-bounce-delay: 0s;
}
[data-slot="rattle-bounce-brick"]:nth-child(4) {
  --rattle-bounce-delay: 0.2s;
}
[data-slot="rattle-bounce-brick"]:nth-child(5) {
  --rattle-bounce-delay: 0.4s;
}
[data-slot="rattle-bounce-brick"]:nth-child(2n) {
  background-color: var(--rattle-bounce-2, #aaa);
}
[data-slot="rattle-bounce-brick"]:nth-child(3n) {
  background-color: var(--rattle-bounce-3, #ccc);
}
@keyframes rattle-bounce-bounce {
  from {
    opacity: 0;
  }
  20%,
  to {
    opacity: 1;
  }

  0% {
    transform: translateY(-400%) rotate(30deg);
  }
  60% {
    transform: rotate(-4deg);
  }
  70% {
    transform: translateY(-10%) rotate(2deg);
  }
  80% {
    transform: rotate(0);
  }
  90% {
    transform: translateY(-5%) rotate(-1deg);
  }
  100% {
    transform: rotate(0);
  }
}
@keyframes rattle-bounce-fall {
  from,
  80% {
    opacity: 1;
  }
  to {
    opacity: 0;
  }

  from {
    transform: rotate(0);
  }
  to {
    transform: translateY(400%) rotate(20deg);
  }
}

/*
 * Reduced motion: opacity only. The bricks fade in and out on the same
 * timeline, without moving.
 */
@keyframes rattle-bounce-fade-in {
  from {
    opacity: 0;
  }
  20%,
  to {
    opacity: 1;
  }
}
@keyframes rattle-bounce-fade-out {
  from,
  80% {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="rattle-bounce-brick"] {
    animation:
      rattle-bounce-fade-in 0.8s ease-in-out var(--rattle-bounce-delay, 0s) both,
      rattle-bounce-fade-out 0.5s cubic-bezier(0.74, 0.03, 1, 1) calc(var(--rattle-bounce-delay, 0s) + 1.4s)
        forwards;
  }
}
`;

/**
 * Five bricks drop in, rattle into a pile, then fall away, once on mount.
 * Remount it (change its `key`) to play it again.
 */
function RattleBounce({ className, ...props }: React.ComponentProps<"div">) {
  const labelled =
    props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined;
  return (
    <div
      data-slot="rattle-bounce"
      role={labelled ? "img" : undefined}
      aria-hidden={labelled ? undefined : true}
      className={cn(
        "relative aspect-square w-full max-w-80 overflow-hidden bg-[var(--rattle-bounce-surface,#fff)]",
        className,
      )}
      {...props}
    >
      <style href="designfrom-rattle-bounce" precedence="default">
        {css}
      </style>
      <div data-slot="rattle-bounce-pile">
        <div data-slot="rattle-bounce-brick" />
        <div data-slot="rattle-bounce-brick" />
        <div data-slot="rattle-bounce-brick" />
        <div data-slot="rattle-bounce-brick" />
        <div data-slot="rattle-bounce-brick" />
      </div>
    </div>
  );
}

export { RattleBounce };
